const e = $('Bei Einzelaufruf').first().json;
if (!/^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$/.test(String(e.empfaenger || ''))) throw new Error('[EPA:400:UNGUELTIGES_FORMAT:' + (e.vorgangs_id || '-') + '] Freigeber ist keine gültige Adresse');
