let meldung = '';
if (status !== 202) { try { const b = JSON.parse(r.body || '{}'); meldung = String((b.error && (b.error.code + ': ' + b.error.message)) || '').slice(0, 200); } catch (err) { meldung = String(r.body || '').slice(0, 200); } }
return [{ json: { gesendet: status === 202, status, meldung } }];

